{
  "technical_and_design_decisions": [
    "For XD 1.0 to 1.1 migration (U1), backward compatibility for public custom module APIs will be maintained where possible, with automated migration scripts provided for common configuration changes to reduce user porting effort.",
    "The Pig integration sample (U2) will target Pig 0.15 (the latest stable version supported by XD 1.1) and be packaged as a standalone sample project with clear execution instructions.",
    "Windows build support (U3) will prioritize Windows Subsystem for Linux 2 (WSL 2) as the primary build environment to minimize platform-specific code changes, with native Windows build support documented for contributors without WSL access.",
    "Windows acceptance tests (U4) will run on AWS EC2 Windows Server 2022 instances, with CI integration via GitHub Actions to enable automated test execution on every pull request to the open source repository.",
    "Spark Streaming processors (U5) will be implemented as two separate modules: a Java-based module using lambdas for simple use cases, and a Scala-based module for advanced use cases, both adhering to XD's standard processor module contract.",
    "The reference guide copyright update (U6) will be applied to the Asciidoctor source documentation file, with the PDF regenerated from source to ensure consistency across all output formats.",
    "The Kafka SI GA upgrade (U7) will be performed on a dedicated feature branch, with backported changes from the XD Kafka module validated against the Kafka SI GA release candidate before merging to main.",
    "The SHDP GA upgrade (U8) will use the latest GA release version, with full regression testing run to identify and resolve any compatibility issues with existing XD functionality."
  ],
  "assumptions": [
    "The developer has full access to the XD codebase, AWS EC2 console, and the project's CI/CD pipeline configuration.",
    "All third-party dependencies (Pig 0.15, Kafka SI GA, SHDP GA) are compatible with XD 1.1's core runtime and the required Java 17+ runtime.",
    "Existing XD acceptance test suites are platform-agnostic enough to run on Windows with only minor path and line-ending adjustments.",
    "The project's reference guide is maintained in Asciidoctor source format in the project's documentation repository.",
    "Custom modules built for XD 1.0 use only public, non-deprecated APIs that are retained in XD 1.1.",
    "The developer has prior working knowledge of the XD codebase, Spring Framework, Apache Spark, Pig, Kafka, and SHDP to reduce learning curve effort."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1 Migration Analysis and Porting Guide Development",
      "activity_description": "Analyze breaking changes between XD 1.0 and 1.1, identify required modifications for custom module porting, and create a user-facing porting guide with step-by-step instructions.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A2",
      "activity_name": "U2 Pig Integration Sample Development",
      "activity_description": "Develop a working Pig script sample integrated with XD's module runtime, add documentation for sample execution, and validate end-to-end functionality of the Pig job within XD.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "U3 Windows Build Environment Setup and Validation",
      "activity_description": "Configure WSL 2 and native Windows build environments for XD, resolve any platform-specific build issues (e.g., path separators, line endings, native dependencies), test full build and unit test execution on Windows, and document setup steps for contributors.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "U4 Windows EC2 Acceptance Test Environment Provisioning",
      "activity_description": "Provision a Windows Server 2022 EC2 instance, install required dependencies (JDK 17+, XD runtime, test tooling), configure network and security settings to enable test execution, and validate the environment is ready for acceptance tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "U4 Windows Acceptance Test Execution and CI Integration",
      "activity_description": "Run the full XD acceptance test suite on the Windows EC2 instance, fix any platform-specific test failures, configure a GitHub Actions CI workflow to run acceptance tests on Windows automatically for all pull requests, and validate the CI pipeline functionality.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "U5 Java Lambda Spark Streaming Processor Implementation",
      "activity_description": "Implement an XD-compliant Spark Streaming data processor using Java lambdas, add unit tests for core functionality and error handling, and validate the processor works with sample streaming data.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A7",
      "activity_name": "U5 Scala Spark Streaming Processor Implementation",
      "activity_description": "Implement an XD-compliant Spark Streaming data processor using Scala, add unit tests for core functionality and error handling, and validate the processor works with sample streaming data.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A8",
      "activity_name": "U6 Reference Guide Copyright Update",
      "activity_description": "Update the copyright year from 2014 to 2015 in the Asciidoctor source file for the XD reference guide, regenerate the PDF output, and validate the updated copyright is correctly displayed in the final PDF document.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "U7 Kafka SI GA Upgrade and Backport",
      "activity_description": "Backport required Kafka XD module changes to the Spring Integration Kafka (SI Kafka) module, upgrade the SI Kafka dependency to the GA release, run integration tests to validate compatibility with existing XD Kafka module configurations, and resolve any conflicts or issues.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A10",
      "activity_name": "U8 SHDP GA Upgrade and Regression Testing",
      "activity_description": "Upgrade the Spring Hadoop Data Processing (SHDP) dependency to the latest GA release, run the full XD regression test suite to identify compatibility issues, and fix any breaking changes affecting existing XD functionality.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 170
  }
}

